/**
 * Card (issue #11) — pure composition, no product meaning.
 *
 * shadcn-compatible part set (Card, CardHeader, CardTitle,
 * CardDescription, CardContent, CardFooter) over the theme's card
 * pairing (`--card` / `--card-foreground`). Card carries no record
 * states, no actions, and no product semantics: it groups, and the
 * content inside speaks (DESIGN.md: state is named by labels, never
 * implied by a container). See `./card.css` and the component contract in
 * `docs/components.md`.
 */

import "./card.css";
import type { ComponentProps } from "react";
import { cx } from "@/lib/utils";

export type CardProps = ComponentProps<"div">;

/** Grouping surface. Renders a plain `div` — no landmark role. */
export function Card({ className, ...props }: CardProps) {
  return <div {...props} className={cx("aug-card", className)} />;
}

export type CardHeaderProps = ComponentProps<"div">;

/** Header block: stacks the title and (optionally) description. */
export function CardHeader({ className, ...props }: CardHeaderProps) {
  return <div {...props} className={cx("aug-card-header", className)} />;
}

export type CardTitleProps = ComponentProps<"h3">;

/**
 * Card title: an `h3` (shadcn convention — real heading semantics
 * rather than a styled div). Consumers own the document outline.
 */
export function CardTitle({ className, children, ...props }: CardTitleProps) {
  return (
    <h3 {...props} className={cx("aug-card-title", "augur-type-heading-2", className)}>
      {children}
    </h3>
  );
}

export type CardDescriptionProps = ComponentProps<"p">;

/** Supporting text under the title, in the metadata voice. */
export function CardDescription({ className, children, ...props }: CardDescriptionProps) {
  return (
    <p {...props} className={cx("aug-card-description", "augur-type-metadata", className)}>
      {children}
    </p>
  );
}

export type CardContentProps = ComponentProps<"div">;

/** Main body block, in the body voice. */
export function CardContent({ className, ...props }: CardContentProps) {
  return <div {...props} className={cx("aug-card-content", "augur-type-body", className)} />;
}

export type CardFooterProps = ComponentProps<"div">;

/** Footer row for actions; children lay out inline. */
export function CardFooter({ className, ...props }: CardFooterProps) {
  return <div {...props} className={cx("aug-card-footer", className)} />;
}

/*
 * Card styles (issue #11).
 *
 * Color: ONLY semantic role custom properties from ../../styles/roles.css
 * (which references generated tokens). No raw color values, no new
 * custom properties.
 *
 * Geometry: panel padding consumes the generated spacing tokens
 * (24px steps to 16px below 600px, per the contract's panel rule); the
 * surface radius consumes the generated rounded token
 * (`--augur-rounded-surface`, 0px — issues #45/#50). Component contract:
 * ../../docs/components.md.
 *
 * Every rule sits in `@layer augur`; this file depends only on the
 * theme (`theme.css`).
 */

@layer augur {

.aug-card {
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  background-color: var(--card);
  color: var(--card-foreground);
  border: 1px solid var(--border);
  border-radius: var(--augur-rounded-surface); /* encoded: 0px */
}

/*
 * Composition spacing (shadcn classic pattern): the header carries the
 * top/bottom rhythm; content and footer close the card. The
 * :first-child rule keeps a headerless composition from opening flush.
 */
.aug-card-header {
  display: flex;
  flex-direction: column;
  gap: var(--augur-spacing-sm); /* space.sm: title-to-description gap */
  padding: var(--augur-spacing-xl); /* space.xl: contract panel padding */
}

.aug-card-content {
  padding: 0 var(--augur-spacing-xl) var(--augur-spacing-xl);
}

.aug-card-footer {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--augur-spacing-sm);
  padding: 0 var(--augur-spacing-xl) var(--augur-spacing-xl);
}

.aug-card > .aug-card-content:first-child,
.aug-card > .aug-card-footer:first-child {
  padding-block-start: var(--augur-spacing-xl);
}

/* Contract panel padding steps to 16px below 600px (composition
   rule for record fields and panels, encoded direction). */
@media (max-width: 599px) {
  .aug-card-header,
  .aug-card-content,
  .aug-card-footer {
    padding-inline: var(--augur-spacing-lg);
    padding-block-start: var(--augur-spacing-lg);
  }

  .aug-card-content,
  .aug-card-footer {
    padding-inline-end: var(--augur-spacing-lg);
    padding-block-end: var(--augur-spacing-lg);
  }

  .aug-card > .aug-card-content:first-child,
  .aug-card > .aug-card-footer:first-child {
    padding-block-start: var(--augur-spacing-lg);
  }
}

/*
 * Typographic margins: the role classes set type only, so block
 * margins are reset here (the components compose the role classes).
 */
.aug-card-title,
.aug-card-description {
  margin: 0;
}

.aug-card-description {
  color: var(--muted-foreground);
}

.aug-card-content > :first-child {
  margin-top: 0;
}

.aug-card-content > :last-child {
  margin-bottom: 0;
}

} /* @layer augur */
